import {APIProvider} from '@vis.gl/react-google-maps';
import {Map, MapCameraChangedEvent} from '@vis.gl/react-google-maps';
import React from 'react';
import GMapMarkers from './GMapMarker.tsx';

type Poi ={ key: string, location: google.maps.LatLngLiteral, status: number }
const locations: Poi[] = [
  {key: 'operaHouse',location: { lat: -33.8567844, lng: 151.213108  }, status: 1},
  {key: 'tarongaZoo', location: { lat: -33.8472767, lng: 151.2188164 }, status: 2},
  {key: 'manlyBeach', location: { lat: -33.8209738, lng: 151.2563253 }, status: 1},
  {key: 'hyderPark', location: { lat: -33.8690081, lng: 151.2052393 }, status: 1},
  {key: 'theRocks', location: { lat: -33.8587568, lng: 151.2058246 }, status: 2},
  {key: 'circularQuay', location: { lat: -33.858761, lng: 151.2055688 }, status: 2},
  {key: 'harbourBridge', location: { lat: -33.852228, lng: 151.2038374 }, status: 1},
  {key: 'kingsCross', location: { lat: -33.8737375, lng: 151.222569 }, status: 1},
  {key: 'botanicGardens', location: { lat: -33.864167, lng: 151.216387 }, status: 2},
  {key: 'museumOfSydney', location: { lat: -33.8636005, lng: 151.2092542 }, status: 1},
  {key: 'maritimeMuseum', location: { lat: -33.869395, lng: 151.198648 }, status: 1},
  {key: 'kingStreetWharf', location: { lat: -33.8665445, lng: 151.1989808 }, status: 1},
  {key: 'aquarium', location: { lat: -33.869627, lng: 151.202146 }, status: 2},
  {key: 'darlingHarbour', location: { lat: -33.87488, lng: 151.1987113 }, status: 1},
  {key: 'barangaroo', location: { lat: - 33.8605523, lng: 151.1972205 }, status: 2},
];

const GMap = () =>{
    
    
    
    return(
      <>
      <div className='map-container'>
        <APIProvider apiKey={'AIzaSyAOqNFQrg3e1paiAJoAVGPQ_9Zu8rzf7og'} onLoad={() => console.log('Maps API has loaded.')}>
        <Map
          mapId='DEMO_MAP_ID'
          defaultZoom={2}
          defaultCenter={ { lat: -0.00665793088812781, lng: 17.856514443765818 } }
          onCameraChanged={ (ev: MapCameraChangedEvent) =>
          console.log('camera changed:', ev.detail.center, 'zoom:', ev.detail.zoom)
          }>
            <GMapMarkers pois={locations}></GMapMarkers>
        </Map>

        </APIProvider>
        
      </div>
      </>
    )
      

}

export default GMap;
